package com.xjtu.iron.idempotent.api.repository;import java.time.Instant;public final class IdempotencyFailureInfo{private final String code,message;private final boolean retryable;private final Instant occurredAt;public IdempotencyFailureInfo(String code,String message,boolean retryable,Instant occurredAt){this.code=code;this.message=message;this.retryable=retryable;this.occurredAt=occurredAt;}public String getCode(){return code;}public String getMessage(){return message;}public boolean isRetryable(){return retryable;}public Instant getOccurredAt(){return occurredAt;}}
